package com.ecommerce.notification.service; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="notifications",indexes=@Index(name="idx_notification_user",columnList="user_id")) public class Notification { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(nullable=false) UUID userId; @Column(nullable=false,length=40) String type; @Column(nullable=false,length=1000) String message; boolean readFlag=false; Instant createdAt=Instant.now(); public UUID getId(){return id;} public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public boolean isReadFlag(){return readFlag;} public void setReadFlag(boolean v){readFlag=v;} public Instant getCreatedAt(){return createdAt;} }